+export interface SignedSessionToken {
+  payload: {
+    id: string;
+    userId: string;
+    issuedAt: number;
+  };
+  signature: string;
+}
+
+const signingKey = process.env.SESSION_SIGNING_KEY || "dev-key";
+
+export const createSession = async (userId: string): Promise<SignedSessionToken> => {
+  const id = randomUUID();
+  const issuedAt = Math.floor(Date.now() / 1000);
+
+  const payload = { id, userId, issuedAt };
+  const payloadStr = JSON.stringify(payload);
+
+  const hmac = createHmac("sha256", signingKey);
+  hmac.update(payloadStr);
+  const signature = hmac.digest("base64");
+
+  await pool.query(
+    "INSERT INTO sessions (id, user_id) VALUES ($1, $2)",
+    [id, userId],
+  );
+
+  return { payload, signature };
+};
+
+export const verifySessionToken = (token: SignedSessionToken): Session | null => {
+  const payloadStr = JSON.stringify(token.payload);
+
+  const hmac = createHmac("sha256", signingKey);
+  hmac.update(payloadStr);
+  const expectedSignature = hmac.digest("base64");
+
+  if (token.signature !== expectedSignature) {
+    return null;
+  }
+
+  return {
+    id: token.payload.id,
+    userId: token.payload.userId,
+    revokedAt: null,
+  };
+};
+
